import{_ as t,o as s,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Test tablette : résultat et procédure","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/atlas/tablet-test.md","filePath":"fr/projects/atlas/tablet-test.md","lastUpdated":1793128957000}'),n={name:"fr/projects/atlas/tablet-test.md"};function i(l,e,o,p,u,c){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="test-tablette-resultat-et-procedure" tabindex="-1">Test tablette : résultat et procédure <a class="header-anchor" href="#test-tablette-resultat-et-procedure" aria-label="Permalink to &quot;Test tablette : résultat et procédure&quot;">​</a></h1><p>Également terminé sur les deux hôtes : <a href="./tablet-uix-dauertest">test UIX tablette de 60 minutes</a>.</p><p>2026-10-19 · App 0.1.327 · HA 2026.10.2 · <code>192.168.178.177</code> / <code>192.168.178.68</code>.</p><p>L’utilisateur confirme 12 et 360 cartes, puis <strong>720 cartes sur les deux hôtes</strong>, avec thèmes et reconnexion.</p><p>Samsung Galaxy Tab A6, Android 11 / LineageOS, Chrome Mobile 155. Après arrêt d’autres applications, le navigateur est jugé fluide. Stream Deck reste inchangé.</p><p>Résultat fonctionnel rapporté, sans mesure FPS/mémoire ni longue durée. Les résultats détaillés séparés portrait/paysage ne sont pas rapportés. Card-Mod 4.2.1 seul avec Bubble 3.4.2 et Mushroom 5.2.3 ; cette première étape ne validait pas UIX ; le test prolongé suivant est lié ci-dessus.</p><p>Sauvegardes complètes avant le test. Tableaux, ressources et états propres retirés ; fichiers WWW dans la corbeille récupérable File Studio. Les anciens liens temporaires sont retirés et ne sont plus actifs.</p><p>Sept projets et six plugins par hôte, 531 fichiers existants capturés sur .177 et neuf sur .68 conservés, avec thèmes initiaux et anciennes entrées de corbeille. Trois sauvegardes complètes récentes par hôte ; sauvegardes PC conservées.</p><p>Pour les futurs tests : vérification légère du navigateur, puis 12, 360 et 720 cartes. Augmenter seulement si fluide ; vérifier portrait/paysage, défilement, états synthétiques, thèmes et reconnexion sans rechargement. Restaurer le thème initial. Créer les tableaux propres visibles dans la barre latérale sans Admin-only. Ne jamais charger Card-Mod et UIX en parallèle.</p><p>Le test UIX d’une heure est terminé. Des mesures indépendantes de latence de rendu et d’évolution mémoire restent ouvertes.</p>',10)])])}const f=t(n,[["render",i]]);export{m as __pageData,f as default};
